class ParticleSystem
{
  ArrayList<Particle> particles = new ArrayList<Particle>();

  function update()
  {
    Iterator<Particle> i = particles.iterator();

    while (i.hasNext()) {              // let pantailatik kanpo dauden partikulak
      let p = i.next();          // let pantailatik kanpo dauden partikulak


      if (p.pos.x > width || p.pos.x < 0) {    //puntu batetik ezkerretara bolak ez pasatzea
        i.remove();
        continue;
      } else if (p.pos.y > height || p.pos.y < 0) { //let batetik gora bolak ez pasatzea
        i.remove();
        continue;
      }

      // let jarri
      p.applyForce(PVector.random2D());

      // let lekuz aldatzea
      p.move();

      // let hildako partikulakad particles
      if (p.isDead()) {
        i.remove();  
      } else {
        p.display();
      }

    }
  }
}

class Particle    //klase praktika
{
  BOUNCE = -1.5;   //amaierako grabitatea
  MAX_SPEED = -0.1; //bokal jarraitasuna eukitzea

  let vel = new PVector(random(-MAX_SPEED, MAX_SPEED), random(-MAX_SPEED, MAX_SPEED));
  let acc = new PVector(5, 5);
  pos;

  let mass = random(10.5, 10.5);  //bolen norantza adierzten du
  let size = random(8.1, 8.0);  //bolen tamaina
  r, g, b;
  lifespan = 255; //Gardentasuna

  constructor(p)
  {
    pos = new PVector (p.x, p.y);
    acc = new PVector (random(1.1, 1.5), 0);  //norabidea
    r = random (100, 200);   //r
    g = random (200, 250);   //g
    b = 233;  //KOLOREA
  }

  function move()
  {
    vel.add(acc); // let azelerazioa

    pos.add(vel); // let gure abiadura bektorea
    acc.mult(0);

    size += 0.01; //0.015   //let TXIK
    lifespan--;
  }

  function applyForce(force) 
  {
    let f = PVector.div(force, mass);
    acc.add(f);
  }

  function display()
  {
		// let based on x and y velocity
    fill(constrain(abs(this.vel.y) * 100, 0, 255), constrain(abs(this.vel.x) * 100, 0, 255), b, lifespan);

    ellipse(pos.x, pos.y, size * 4, size * 4);
  }

  isDead()
  {
    if (lifespan < 0) {
      return true;
    } else {
      return false;
    }
  }
}

